// Generated by Claude/specs/courses-tools/sync-ielts-exams.js from Claude/specs/lxd-course-ielts-exams/exam-02/ (farin-lxd). Do not hand-edit.
(function(E){ const x = E["exam-02"] = E["exam-02"] || {units:{}}; (x.units = x.units || {})["x02-w2"] = {"id":"x02-w2","patterns":["W2-discuss","W2T-tech","TR-halfquestion"],"title":{"en":"Writing Task 2","tr":"Writing Task 2","fa":"Writing Task 2 (نوشتن، تکلیف ۲)"},"objective":{"en":"In this lesson you will learn to write a \"discuss both views\" essay: explain each view fairly in its own paragraph, give your own opinion from the introduction to the conclusion, and support every point with a reason and an example, in at least 250 words.","tr":"Bu derste \"iki görüşü tartış\" türünde bir deneme yazmayı öğreneceksin: her görüşü kendi paragrafında adil biçimde açıklayacak, kendi görüşünü girişten sonuca kadar koruyacak ve her noktayı bir neden ve bir örnekle destekleyeceksin, en az 250 kelimeyle.","fa":"در این درس یاد می‌گیری یک مقاله‌ی «هر دو دیدگاه را بررسی کن» بنویسی: هر دیدگاه را در پاراگراف خودش منصفانه توضیح بدهی، نظرت را از مقدمه تا نتیجه نگه داری و هر نکته را با یک دلیل و یک مثال پشتیبانی کنی، در دست‌کم ۲۵۰ کلمه."},"sessions":[["explain"],["writing"],["exit"]],"explain":{"title":{"en":"Writing Task 2: discuss both views","tr":"Writing Task 2: iki görüşü tartış","fa":"Writing Task 2: هر دو دیدگاه را بررسی کن"},"objective":{"en":"In this lesson you will learn to write a \"discuss both views\" essay: explain each view fairly in its own paragraph, give your own opinion from the introduction to the conclusion, and support every point with a reason and an example, in at least 250 words.","tr":"Bu derste \"iki görüşü tartış\" türünde bir deneme yazmayı öğreneceksin: her görüşü kendi paragrafında adil biçimde açıklayacak, kendi görüşünü girişten sonuca kadar koruyacak ve her noktayı bir neden ve bir örnekle destekleyeceksin, en az 250 kelimeyle.","fa":"در این درس یاد می‌گیری یک مقاله‌ی «هر دو دیدگاه را بررسی کن» بنویسی: هر دیدگاه را در پاراگراف خودش منصفانه توضیح بدهی، نظرت را از مقدمه تا نتیجه نگه داری و هر نکته را با یک دلیل و یک مثال پشتیبانی کنی، در دست‌کم ۲۵۰ کلمه."},"stats":[{"label":{"en":"Words","tr":"Kelime","fa":"کلمه"},"value":"250+"},{"label":{"en":"Time","tr":"Süre","fa":"زمان"},"value":{"en":"40 min","tr":"40 dk","fa":"۴۰ دقیقه"}},{"label":{"en":"Paragraphs","tr":"Paragraf","fa":"پاراگراف"},"value":"4"}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: concerts or streaming?","tr":"Bu sınav: konser mi, çevrim içi dinleme mi?","fa":"این آزمون: کنسرت یا پخش آنلاین؟"},"intro":{"en":"Task 2 is one essay question. \"Discuss both views\" is the second most frequent type after \"agree or disagree\", and questions about technology and how we spend our free time come up often.","tr":"Task 2 tek bir deneme sorusudur. \"İki görüşü tartış\", \"katılıyor musun\" türünden sonra en sık çıkan ikinci türdür; teknoloji ve boş zamanı nasıl geçirdiğimizle ilgili sorular sık gelir.","fa":"Task 2 یک سؤال مقاله است. «هر دو دیدگاه را بررسی کن» بعد از «موافقی یا مخالف» دومین نوع پرتکرار است و سؤال‌هایی درباره‌ی فناوری و اینکه وقت آزادمان را چطور می‌گذرانیم زیاد می‌آیند."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x02-w2-ctx","exam":true,"patterns":["W2-discuss","W2T-tech"],"often":{"pattern":"W2-discuss","n":17,"of":76,"label":{"en":"Comes up often in the real exam: 17 of the last 76 Task 2 questions","tr":"Gerçek sınavda sık çıkar: son 76 Task 2 sorusunun 17’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۷ سؤال از ۷۶ سؤالِ اخیرِ Task 2"}},"title":{"en":"Live music or music at home?","tr":"Canlı müzik mi, evde müzik mi?","fa":"موسیقی زنده یا موسیقی در خانه؟"},"asks":{"en":"A \"discuss both views\" essay: some people prefer live concerts, others prefer streaming music at home. You must explain both views fairly and then give your own opinion. Technology and media are a common Task 2 theme.","tr":"\"İki görüşü tartış\" türünde bir deneme: bazı insanlar canlı konserleri, bazıları evde müzik dinlemeyi tercih eder. İki görüşü de adil biçimde açıklamalı, sonra kendi görüşünü vermelisin. Teknoloji ve medya sık çıkan bir Task 2 konusudur.","fa":"یک مقاله‌ی «هر دو دیدگاه را بررسی کن»: بعضی‌ها کنسرت زنده را ترجیح می‌دهند و بعضی‌ها گوش دادن به موسیقی در خانه را. باید هر دو دیدگاه را منصفانه توضیح بدهی و بعد نظر خودت را بگویی. فناوری و رسانه موضوع رایجی در Task 2 است."},"fields":["View 1: live concerts","View 2: streaming at home","Your opinion","Examples"],"words":[{"a":"a live performance","b":"seeing musicians play in person","tr":"canlı performans","fa":"اجرای زنده"},{"a":"streaming","b":"playing music online without buying it","tr":"çevrim içi dinleme","fa":"پخش آنلاین"},{"a":"atmosphere","b":"the feeling in a crowd / the energy","tr":"atmosfer","fa":"حال‌وهوا"},{"a":"affordable","b":"not too expensive","tr":"uygun fiyatlı","fa":"مقرون‌به‌صرفه"},{"a":"convenient","b":"easy, whenever you want","tr":"kullanışlı, zahmetsiz","fa":"راحت و در دسترس"},{"a":"a wide range of","b":"a huge choice of","tr":"geniş bir yelpaze","fa":"طیف گسترده‌ای از"},{"a":"sound quality","b":"how good the music sounds","tr":"ses kalitesi","fa":"کیفیت صدا"},{"a":"a shared experience","b":"enjoying something together","tr":"paylaşılan bir deneyim","fa":"تجربه‌ی مشترک"},{"a":"proponents of","b":"people who support","tr":"... savunucuları","fa":"طرفداران"},{"a":"on the other hand","b":"however / by contrast","tr":"öte yandan","fa":"از طرف دیگر"},{"a":"in my view","b":"I would argue that / personally, I believe","tr":"bence","fa":"به نظر من"},{"a":"complement","b":"add to rather than replace","tr":"tamamlamak","fa":"تکمیل کردن"}],"traps":[{"en":"Half the question. \"Discuss both these views and give your own opinion\" has three jobs: view 1, view 2 and your opinion. Missing any of them leaves the question half answered.","tr":"Sorunun yarısı. \"Discuss both these views and give your own opinion\" üç iş ister: 1. görüş, 2. görüş ve senin görüşün. Birini atlarsan soru yarım kalır.","fa":"نصفِ سؤال. «Discuss both these views and give your own opinion» سه کار دارد: دیدگاه ۱، دیدگاه ۲ و نظر خودت. اگر یکی را جا بیندازی، به سؤال نصفه جواب داده‌ای."},{"en":"Your opinion only in the last line. Show your position in the introduction too, so the reader knows where the essay is going.","tr":"Görüşünü yalnızca son satırda vermek. Okur denemenin nereye gittiğini bilsin diye tutumunu girişte de göster.","fa":"نظرت فقط در خط آخر. موضعت را در مقدمه هم نشان بده تا خواننده بداند مقاله به کجا می‌رود."}],"example":{"text":"Question: Some people think children should learn to cook at school. Others think this should be taught at home. Discuss both these views and give your own opinion.","item":"Which opening sentence shows a position?","answer":"While both settings have a role, I believe schools are better placed to teach basic cooking to every child.","why":{"en":"It mentions both views and gives the writer’s opinion at once.","tr":"İki görüşten de söz ediyor ve yazarın görüşünü hemen veriyor.","fa":"از هر دو دیدگاه اسم می‌برد و نظر نویسنده را فوراً می‌گوید."}}},{"id":"W2T-tech","ctx":["W2-discuss","W2-advdis","W2T-tech"],"title":{"en":"Technology and media","tr":"Teknoloji ve medya","fa":"فناوری و رسانه"},"asks":{"en":"Questions about technology in daily life: watching films at home, books or screens, driverless cars, paying by phone, privacy, and sharing scientific research.","tr":"Günlük hayatta teknoloji üzerine sorular: filmleri evde izlemek, kitap ya da ekran, sürücüsüz arabalar, telefonla ödeme, mahremiyet ve bilimsel araştırmaları paylaşmak.","fa":"سؤال‌هایی درباره‌ی فناوری در زندگی روزمره: تماشای فیلم در خانه، کتاب یا صفحه‌نمایش، خودروی بی‌راننده، پرداخت با گوشی، حریم خصوصی، و به اشتراک گذاشتن پژوهش‌های علمی."},"fields":["Cinemas or watching films at home? Discuss both views.","Paying by phone app: advantages and disadvantages?","Should famous people have more privacy?","Will printed books disappear?","Should scientific research be shared freely?"],"words":[{"a":"the internet","b":"online / the web","tr":"internet","fa":"اینترنت"},{"a":"phones and computers","b":"digital devices","tr":"dijital cihazlar","fa":"دستگاه‌های دیجیتال"},{"a":"news","b":"the media / news outlets","tr":"medya","fa":"رسانه‌ها"},{"a":"apps","b":"online services / platforms","tr":"platformlar","fa":"پلتفرم‌ها"},{"a":"private life","b":"privacy / personal data","tr":"mahremiyet, kişisel veri","fa":"حریم خصوصی"},{"a":"without cash","b":"cashless payment / contactless","tr":"nakitsiz ödeme","fa":"پرداخت بدون پول نقد"},{"a":"cars that drive themselves","b":"driverless / self-driving cars","tr":"sürücüsüz arabalar","fa":"خودروهای بی‌راننده"},{"a":"at home","b":"streaming / on-demand viewing","tr":"dijital yayın","fa":"تماشای آنلاین"},{"a":"use too much","b":"dependence on / addiction to","tr":"bağımlılık","fa":"وابستگی"},{"a":"new inventions","b":"technological advances","tr":"teknolojik gelişmeler","fa":"پیشرفت‌های فناوری"},{"a":"old people find it hard","b":"the digital divide","tr":"dijital uçurum","fa":"شکاف دیجیتال"},{"a":"fake news","b":"misinformation","tr":"yanlış bilgi","fa":"اطلاعات نادرست"}],"traps":[{"en":"Technology questions tempt you to write about technology in general. Stay on the exact technology in the question.","tr":"Teknoloji soruları genel olarak teknoloji hakkında yazmaya iter. Sorudaki belirli teknolojiden ayrılma.","fa":"سؤال‌های فناوری وسوسه‌ات می‌کنند درباره‌ی فناوری به‌طور کلی بنویسی. روی همان فناوری مشخص سؤال بمان."},{"en":"In \"discuss both views\", present the view you disagree with fairly, then reject it with a reason.","tr":"\"İki görüşü tartış\"ta katılmadığın görüşü adil biçimde sun, sonra gerekçeyle reddet.","fa":"در «هر دو دیدگاه را بررسی کن» دیدگاهی را که با آن مخالفی منصفانه بگو و بعد با دلیل ردش کن."}],"example":{"text":"Question: Some people think that cinemas will soon disappear because people watch films at home. Others think cinemas will always be popular. Discuss both views and give your opinion.","item":"Write a thesis sentence.","answer":"Although home streaming has reduced cinema audiences, I believe cinemas will survive, because people still value watching films together on a big screen.","why":{"en":"Both views appear, with one clear opinion and a reason.","tr":"İki görüş de var; tek ve net bir görüş ve bir neden.","fa":"هر دو دیدگاه آمده، با یک نظر روشن و یک دلیل."}},"ideas":["+ Streaming is cheaper and lets people watch when they want.","- Cinemas offer a shared experience and big-screen quality.","+ Paying by phone is fast and leaves a record of spending.","- Older people and those without phones are excluded.","+ Open research speeds up medical discoveries.","- Companies may stop funding research they cannot profit from."],"general":true,"patterns":["W2-discuss","W2-advdis","W2T-tech"],"often":{"pattern":"W2T-tech","n":9,"of":76,"label":{"en":"Comes up often in the real exam: 9 of the last 76 Task 2 questions","tr":"Gerçek sınavda sık çıkar: son 76 Task 2 sorusunun 9’unda","fa":"در آزمون واقعی زیاد می‌آید: در ۹ سؤال از ۷۶ سؤالِ اخیرِ Task 2"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Forty minutes, four paragraphs","tr":"Kırk dakika, dört paragraf","fa":"چهل دقیقه، چهار پاراگراف"},"body":{"en":"Write at least 250 words in about 40 minutes. Plan for five minutes, write for thirty, and check for five. Use four paragraphs: introduction with your position, view 1, view 2 (usually the one you agree with), and a conclusion.","tr":"Yaklaşık 40 dakikada en az 250 kelime yaz. Beş dakika planla, otuz dakika yaz, beş dakika kontrol et. Dört paragraf kullan: tutumunla birlikte giriş, 1. görüş, 2. görüş (genelde katıldığın görüş) ve sonuç.","fa":"در حدود ۴۰ دقیقه دست‌کم ۲۵۰ کلمه بنویس. پنج دقیقه برنامه بریز، سی دقیقه بنویس و پنج دقیقه بازبینی کن. چهار پاراگراف: مقدمه همراه با موضعت، دیدگاه ۱، دیدگاه ۲ (معمولاً همانی که با آن موافقی) و نتیجه."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"One view per paragraph","tr":"Her paragrafta bir görüş","fa":"در هر پاراگراف یک دیدگاه"},"steps":[{"en":"Underline the two views and the instruction: \"discuss both\" + \"your own opinion\".","tr":"İki görüşün ve talimatın altını çiz: \"discuss both\" + \"your own opinion\".","fa":"زیر دو دیدگاه و دستور خط بکش: «discuss both» + «your own opinion»."},{"en":"For each view, write one main reason and one example, as its supporters would.","tr":"Her görüş için, onu savunanların yapacağı gibi bir ana neden ve bir örnek yaz.","fa":"برای هر دیدگاه یک دلیل اصلی و یک مثال بنویس، همان‌طور که طرفدارانش می‌گویند."},{"en":"Decide your opinion before you write, and state it in the introduction and again in the conclusion.","tr":"Yazmaya başlamadan görüşüne karar ver; onu girişte ve sonuçta tekrar söyle.","fa":"قبل از نوشتن نظرت را مشخص کن و آن را در مقدمه و دوباره در نتیجه بگو."}]},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Report a view, then give yours","tr":"Bir görüşü aktar, sonra kendininkini söyle","fa":"اول دیدگاه دیگران را بگو، بعد نظر خودت را"},"table":{"headers":{"en":["Job","Phrase"],"tr":["Görev","İfade"],"fa":["کار","عبارت"]},"rows":[["report view 1","Supporters of live music argue that..."],["report view 2","Others, however, believe that..."],["give a reason","This is because... / The main reason is that..."],["give an example","For example, ... / A good example of this is..."],["your opinion","In my view, ... / I would argue that..."]]}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One body paragraph opening, step by step","tr":"Bir gövde paragrafının açılışı, adım adım","fa":"شروع یک پاراگراف بدنه، قدم به قدم"},"instruction":"Question: Some people prefer to read news online, while others prefer printed newspapers. Discuss both these views and give your own opinion.","item":"Write the first two sentences of the paragraph about printed newspapers.","answer":"Supporters of printed newspapers argue that they are more reliable than many websites. This is because their articles are usually checked by experienced editors before they are published.","walk":[{"en":"Report the view, not your own opinion: \"Supporters of... argue that\".","tr":"Kendi görüşünü değil, o görüşü aktar: \"Supporters of... argue that\".","fa":"دیدگاه را گزارش کن، نه نظر خودت را: «Supporters of... argue that»."},{"en":"Give one main reason: they are more reliable.","tr":"Tek bir ana neden ver: daha güvenilirler.","fa":"یک دلیل اصلی بده: قابل‌اعتمادترند."},{"en":"Explain the reason in the next sentence: editors check the articles.","tr":"Nedeni bir sonraki cümlede açıkla: editörler yazıları kontrol ediyor.","fa":"دلیل را در جمله‌ی بعد توضیح بده: ویراستارها مطالب را بررسی می‌کنند."}]},"quick":{"prompt":"An essay explains both views well but never says which one the writer prefers. What is missing?","options":["an example","the writer’s own opinion","a title"],"correct":1,"why":{"en":"The question asks you to \"give your own opinion\" as well as discuss both views.","tr":"Soru, iki görüşü tartışmanın yanında \"kendi görüşünü vermeni\" de istiyor.","fa":"سؤال علاوه بر بررسی هر دو دیدگاه می‌خواهد «نظر خودت را هم بگویی»."}},"remember":{"en":"Both views fairly, one per paragraph, and your opinion clear from the first paragraph to the last.","tr":"İki görüş de adilce, her biri bir paragrafta; görüşün de ilk paragraftan son paragrafa kadar net.","fa":"هر دو دیدگاه منصفانه، هر کدام در یک پاراگراف، و نظرت از پاراگراف اول تا آخر روشن."},"type":"explain","id":"c-x02-w2-e","course":"ielts-exams","exam":"exam-02","unit":"x02-w2"},"writing":{"taskKind":"exam","title":{"en":"Concerts or streaming at home?","tr":"Konser mi, evde çevrim içi dinleme mi?","fa":"کنسرت یا پخش آنلاین در خانه؟"},"task":"task2","reviewLabel":{"en":"Exam 2 · Writing Task 2 (discuss both views: live concerts versus streaming music at home)"},"timed":40,"minWords":250,"ctx":["W2-discuss","W2T-tech"],"prompt":{"en":"You should spend about 40 minutes on this task. Write about the following topic: Some people think that going to live concerts is the best way to enjoy music. Others believe that listening to music at home through streaming services is a better experience. Discuss both these views and give your own opinion. Give reasons for your answer and include any relevant examples from your own knowledge or experience. Write at least 250 words.","tr":"Bu göreve yaklaşık 40 dakika ayırmalısın. Şu konu hakkında yaz: Bazı insanlar müzikten zevk almanın en iyi yolunun canlı konserlere gitmek olduğunu düşünür. Bazıları ise evde çevrim içi müzik servisleriyle dinlemenin daha iyi bir deneyim olduğuna inanır. İki görüşü de tartış ve kendi görüşünü ver. Cevabın için nedenler göster ve kendi bilgi ya da deneyiminden ilgili örnekler ekle. En az 250 kelime yaz.","fa":"باید حدود ۴۰ دقیقه برای این تکلیف وقت بگذاری. درباره‌ی موضوع زیر بنویس: بعضی‌ها فکر می‌کنند رفتن به کنسرت زنده بهترین راه لذت بردن از موسیقی است. بعضی دیگر باور دارند گوش دادن به موسیقی در خانه با سرویس‌های پخش آنلاین تجربه‌ی بهتری است. هر دو دیدگاه را بررسی کن و نظر خودت را بگو. برای جوابت دلیل بیاور و از دانسته‌ها یا تجربه‌ی خودت مثال‌های مرتبط بزن. دست‌کم ۲۵۰ کلمه بنویس."},"model":"Music has never been easier to find. With a phone and a streaming service, almost any song ever recorded is available in seconds, yet concert halls and festivals are still full. While both ways of listening have clear advantages, I believe that live concerts offer an experience that streaming cannot replace.\n\nThose who prefer listening at home make a strong case. Streaming is cheap and convenient: for the price of a single concert ticket, a listener can enjoy a whole year of unlimited music, chosen to suit any mood or activity. It also allows people to discover a far wider range of artists than they could ever see in person. A student in a small town, for example, can listen to musicians from every continent without leaving home, which would be impossible if live performance were the only option.\n\nSupporters of live music, however, argue that a concert is more than a way of hearing songs. Being part of a crowd creates a shared experience, as thousands of people react to the same moment together. Musicians also perform differently in front of an audience, changing songs, talking to the crowd and taking risks that would never appear on a recording. Many people remember a single concert for years, whereas few can recall a particular afternoon of streaming.\n\nIn my view, the second argument is more convincing, although the two forms are not really competitors. Streaming is ideal for everyday listening and for discovering new artists, and it often leads people to concerts rather than replacing them. A live performance remains the fullest way to enjoy music, and for that reason it is worth the higher cost, at least from time to time.","moves":[{"label":{"en":"1 Introduction: the topic and your position","tr":"1 Giriş: konu ve tutumun","fa":"۱ مقدمه: موضوع و موضع تو"},"text":"While both ways of listening have clear advantages, I believe that live concerts offer an experience that streaming cannot replace."},{"label":{"en":"2 View 1, with a reason and an example","tr":"2 1. görüş, bir neden ve bir örnekle","fa":"۲ دیدگاه ۱، با یک دلیل و یک مثال"},"text":"Those who prefer listening at home make a strong case... A student in a small town, for example, can listen to musicians from every continent..."},{"label":{"en":"3 View 2, the one you agree with","tr":"3 2. görüş, katıldığın görüş","fa":"۳ دیدگاه ۲، همانی که با آن موافقی"},"text":"Supporters of live music, however, argue that a concert is more than a way of hearing songs..."},{"label":{"en":"4 Conclusion: your opinion again","tr":"4 Sonuç: görüşün yeniden","fa":"۴ نتیجه: دوباره نظر تو"},"text":"In my view, the second argument is more convincing, although the two forms are not really competitors..."}],"rubricBands":{"note":{"en":"Score each line from 0 to 3. Read the line for the score you choose: it tells you what to improve next.","tr":"Her satırı 0’dan 3’e puanla. Seçtiğin puanın satırını oku: bir sonraki adımda neyi geliştireceğini söyler.","fa":"به هر خط از ۰ تا ۳ نمره بده. توضیحِ نمره‌ای را که انتخاب می‌کنی بخوان: می‌گوید قدم بعدی چه چیزی را بهتر کنی."},"order":["task","organised","words","sentences"],"task":[{"en":"The question is not really answered; no clear position.","tr":"Soru tam olarak cevaplanmamış; net bir tutum yok.","fa":"در واقع به سؤال جواب داده نشده؛ موضع روشنی نیست."},{"en":"A position, but only part of the question is answered, or ideas are not explained.","tr":"Bir tutum var ama sorunun yalnızca bir kısmı cevaplanmış ya da fikirler açıklanmamış.","fa":"موضعی هست، اما فقط بخشی از سؤال جواب داده شده یا ایده‌ها توضیح داده نشده‌اند."},{"en":"Every part answered, one clear position, main ideas supported.","tr":"Her kısım cevaplanmış, tek ve net bir tutum, ana fikirler desteklenmiş.","fa":"به همه‌ی بخش‌ها جواب داده شده، یک موضع روشن هست و ایده‌های اصلی پشتیبانی شده‌اند."},{"en":"A clear, consistent position; ideas fully explained with relevant examples.","tr":"Net ve tutarlı bir tutum; fikirler yerinde örneklerle tam açıklanmış.","fa":"موضعی روشن و یکدست؛ ایده‌ها با مثال‌های مرتبط کامل توضیح داده شده‌اند."}],"organised":[{"en":"No clear paragraphs.","tr":"Net paragraflar yok.","fa":"پاراگراف‌های روشنی ندارد."},{"en":"Paragraphs, but more than one main idea in each, or forced linking words.","tr":"Paragraflar var ama her birinde birden fazla ana fikir ya da zorlama bağlaçlar.","fa":"پاراگراف دارد، اما در هر کدام بیش از یک ایده‌ی اصلی هست یا کلمه‌های ربط تصنعی‌اند."},{"en":"Introduction, body paragraphs with one idea each, conclusion.","tr":"Giriş, her biri tek fikirli gövde paragrafları, sonuç.","fa":"مقدمه، پاراگراف‌هایی که هر کدام یک ایده دارند، نتیجه."},{"en":"A logical flow from start to end; linking is natural.","tr":"Baştan sona mantıklı bir akış; bağlantılar doğal.","fa":"جریانی منطقی از اول تا آخر؛ ربط‌ها طبیعی‌اند."}],"words":[{"en":"Very basic words; the question is copied.","tr":"Çok temel kelimeler; soru kopyalanmış.","fa":"کلمه‌های خیلی ساده؛ صورت سؤال کپی شده."},{"en":"Topic words repeated; some wrong word choices.","tr":"Konu kelimeleri tekrarlanmış; bazı yanlış kelime seçimleri.","fa":"کلمه‌های موضوع تکرار شده‌اند؛ چند انتخاب کلمه‌ی غلط هست."},{"en":"Topic words used well; the question is said in other words.","tr":"Konu kelimeleri iyi kullanılmış; soru başka sözcüklerle anlatılmış.","fa":"کلمه‌های موضوع خوب به کار رفته‌اند؛ سؤال با کلمه‌های دیگر بیان شده."},{"en":"Precise, natural topic words; almost no errors.","tr":"Yerinde, doğal konu kelimeleri; neredeyse hatasız.","fa":"کلمه‌های موضوعِ دقیق و طبیعی؛ تقریباً بی‌غلط."}],"sentences":[{"en":"Mostly short sentences with frequent errors.","tr":"Çoğunlukla kısa cümleler, sık hatalar.","fa":"بیشتر جمله‌های کوتاه با غلط‌های زیاد."},{"en":"Some longer sentences; errors sometimes make the meaning unclear.","tr":"Bazı uzun cümleler; hatalar bazen anlamı belirsizleştiriyor.","fa":"چند جمله‌ی بلندتر؛ غلط‌ها گاهی معنی را نامفهوم می‌کنند."},{"en":"A mix of sentence types, including passives; errors rarely affect the meaning.","tr":"Edilgen yapılar dahil çeşitli cümle türleri; hatalar anlamı nadiren etkiliyor.","fa":"ترکیبی از انواع جمله، از جمله مجهول؛ غلط‌ها به‌ندرت روی معنی اثر می‌گذارند."},{"en":"A wide range of sentences, almost all accurate.","tr":"Çok çeşitli cümleler, neredeyse hepsi doğru.","fa":"جمله‌های خیلی متنوع، تقریباً همه درست."}]},"rubric":["Covers the task: both views explained, a clear opinion, and ideas supported with reasons and examples.","Organised: an introduction, one paragraph for each view, and a conclusion; one main idea per paragraph.","Words: precise words for the topic and for reporting views; the question is said in other words.","Sentences: a mix of simple and complex sentences, with few errors."],"rubricI18n":{"tr":["Görevi karşılıyor: iki görüş de açıklanmış, net bir görüş var ve fikirler neden ve örneklerle desteklenmiş.","Düzenli: giriş, her görüş için bir paragraf ve sonuç; her paragrafta tek ana fikir.","Kelimeler: konu ve görüş aktarma için yerinde kelimeler; soru başka sözcüklerle anlatılmış.","Cümleler: basit ve karmaşık cümlelerin karışımı, az hata."],"fa":["تکلیف را پوشش می‌دهد: هر دو دیدگاه توضیح داده شده‌اند، نظری روشن هست و ایده‌ها با دلیل و مثال پشتیبانی شده‌اند.","منظم است: مقدمه، برای هر دیدگاه یک پاراگراف و نتیجه؛ در هر پاراگراف یک ایده‌ی اصلی.","کلمه‌ها: کلمه‌های دقیق برای موضوع و برای نقل دیدگاه‌ها؛ سؤال با کلمه‌های دیگر بیان شده.","جمله‌ها: ترکیبی از جمله‌های ساده و مرکب، با غلط کم."]},"type":"writing","id":"c-x02-w2-w","course":"ielts-exams","exam":"exam-02","unit":"x02-w2"},"exit":{"type":"exit","items":[{"tests":"word","point":3,"prompt":"\"Online music is convenient.\" Convenient means...","options":["easy to use whenever you want","very expensive","old-fashioned"],"correct":0,"why":{"en":"Convenient = easy, fitting into your day without effort.","tr":"Convenient = kolay, zahmetsizce gününe uyan.","fa":"convenient یعنی راحت، بدون زحمت در برنامه‌ی روزت جا می‌شود."}},{"tests":"paraphrase","point":3,"prompt":"Which phrase reports someone else’s view, not yours?","options":["In my view...","I would argue that...","Supporters of this idea argue that..."],"correct":2,"why":{"en":"\"Supporters... argue\" reports others; the other two give your own opinion.","tr":"\"Supporters... argue\" başkalarını aktarır; diğer ikisi senin görüşünü verir.","fa":"«Supporters... argue» نظر دیگران را نقل می‌کند؛ دو تای دیگر نظر خودت را می‌گویند."}},{"tests":"method","point":2,"prompt":"Where should your opinion appear in a \"discuss both views\" essay?","options":["only in the last sentence","in the introduction and again in the conclusion","nowhere: just describe the views"],"correct":1,"why":{"en":"State it early so the reader can follow it, and repeat it in the conclusion.","tr":"Okur takip edebilsin diye erkenden söyle ve sonuçta tekrar et.","fa":"زود بگو تا خواننده دنبالش کند و در نتیجه تکرارش کن."}},{"tests":"trap","point":1,"prompt":"An essay discusses only the view the writer agrees with. What is the problem?","options":["Half the question is not answered","It is too long","It needs a title"],"correct":0,"why":{"en":"\"Discuss both these views\" means both: the other view needs its own paragraph.","tr":"\"Discuss both these views\" ikisini de ister: diğer görüşün de kendi paragrafı olmalı.","fa":"«Discuss both these views» یعنی هر دو: دیدگاه دیگر هم پاراگراف خودش را لازم دارد."}}],"id":"c-x02-w2-x","course":"ielts-exams","exam":"exam-02","unit":"x02-w2"}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
